import AxeBuilder from '@axe-core/playwright' /* eslint-disable-line import-x/no-named-as-default */
import test from '@playwright/test'

import { LANGS } from '../../src/content/nav'
import { checkSiteImprove } from './helpers/siteimprove'
import { PledgesPage } from './pages/pledgesPage'

/*
 * No aria or screenshot goldens yet: goldens are CI-canonical and generated by the Update
 * baselines workflow, and the list changes with every new entry.
 */
for (const lang of LANGS) {
    test.describe(`Pledges Page (${lang})`, () => {
        test('should render', async ({ page }) => {
            const pledgesPage = new PledgesPage(page, lang)
            await pledgesPage.goTo()

            await pledgesPage.checkContent()
        })

        test('should pass accessibility test', async ({ page }) => {
            const pledgesPage = new PledgesPage(page, lang)
            await pledgesPage.goTo()

            const accessibilityScanResults = await new AxeBuilder({ page }).disableRules(['color-contrast']).analyze()
            test.expect(accessibilityScanResults.violations).toEqual([])
        })

        test('should pass siteimprove check', async ({ page }) => {
            const pledgesPage = new PledgesPage(page, lang)
            await pledgesPage.goTo()

            await checkSiteImprove(page)
        })
    })
}

test.describe('Election page pledges teaser', () => {
    test('should link to the pledges page', async ({ page }) => {
        await page.goto('/fi/eduskuntavaalit/')

        const teaser = page.locator('#sitoumukset')
        await test.expect(teaser.locator('li[data-pledge-id]').first()).toBeAttached()
        await test.expect(teaser.locator('a.link-rule')).toHaveAttribute('href', '/fi/eduskuntavaalit/sitoumukset/')
    })
})
